//! Smart Photos — scaffold.
//!
//! Protocol-first app (PHOTOS-SPECS §5): the app depends on the
//! `smart-protocol-rs` domains (files / media / storage / camera) through
//! the gateway traits in [`protocol`]. Nothing below opens a file, device or
//! socket directly — backends implementing those traits are disposable.
//!
//! Non-destructive law (§7): the image bytes are never modified; edits write
//! a sidecar and bump `edit_generation`, which participates in the thumb
//! cache key (§4.2). Export is the only place pixels are baked.
//!
//! # Sidebar / behaviour rule
//! The single sidebar and its behaviour are owned by `smart-ui-egui`
//! (`smart_ui_egui::photos::Photos`). This crate re-exports that type and
//! delegates view state to it — it never duplicates sidebar or control code
//! here. [`PhotoApp`] wraps one instance.
pub mod a11y;
pub mod capture;
pub mod dup;
pub mod editor;
pub mod exif;
pub mod import;
pub mod model;
pub mod picker;
pub mod protocol;
pub mod scan;
pub mod search;
pub mod settings;
pub mod thumb_cache;
pub mod trash;
pub mod viewer;
pub mod xmp;

/// Read-only re-export of the shared egui Photos view state — the one
/// sidebar/behaviour implementation. No duplicate code lives in this crate.
pub use smart_ui_egui::photos::Photos;
/// Read-only re-export of the shared editor values (8 presets live here).
pub use smart_ui_egui::photos::Adjust;

/// Protocol-first application state. Holds the index, caches and undo log;
/// every backend is injected as a trait object, never hard-coded.
pub struct PhotoApp {
    /// The shared sidebar/view behaviour from `smart-ui-egui`.
    pub photos: Photos,
    /// Indexed library records.
    pub library: Vec<model::PhotoRecord>,
    /// Disk + memory thumbnail caches (500 MB LRU, pool of 8).
    pub thumbs: thumb_cache::ThumbCache,
    /// Reversible editor operation log (100-deep).
    pub undo: editor::UndoLog,
    /// Persisted file-manager-style settings.
    pub settings: settings::PhotosSettings,
    /// Disposable backend handle (swap Local → MTP/Android/iOS).
    pub gateway: Box<dyn protocol::FileGateway>,
}

impl PhotoApp {
    pub fn new(gateway: Box<dyn protocol::FileGateway>) -> Self {
        Self {
            photos: Photos::default(),
            library: Vec::new(),
            thumbs: thumb_cache::ThumbCache::new(
                thumb_cache::DEFAULT_CACHE_MB,
                thumb_cache::BIG_THUMB_POOL,
            ),
            undo: editor::UndoLog::new(editor::UNDO_DEPTH),
            settings: settings::PhotosSettings::default(),
            gateway,
        }
    }

    /// Current records (honest: truncated scans report partial state).
    pub fn records(&self) -> &[model::PhotoRecord] {
        &self.library
    }

    /// Apply one reversible editor operation through the undo log.
    pub fn apply(&mut self, op: editor::EditOp) {
        self.undo.apply(op);
    }
}

/// Native entry point — thin binary calls this. The viewer, filmstrip and
/// settings chrome are drawn by the egui app shell in [`viewer`].
pub fn run_native() -> eframe::Result {
    let gateway = protocol::LocalGateway::default();
    let app = PhotoApp::new(Box::new(gateway));
    // Delegate the egui event loop to the shared suite frontend, which owns
    // the sidebar, depth primitives and window. `PhotoApp` state is what a
    // second process would map over the protocol contract (§5).
    let _ = app;
    smart_ui_egui::run_native()
}

//! Photo identity, classification and records (PHOTOS-SPECS §8).
//!
//! `PhotoId = first 16 bytes of BLAKE3(dev ‖ inode)` — the path is excluded
//! so a rename keeps identity. The egui `Location` stays the *address*.

use blake3::Hasher;
use serde::{Deserialize, Serialize};

/// 128-bit photo identity.
pub type PhotoId = [u8; 16];

/// Classify by extension per §8.2 (F9 `from_extension` adopted verbatim).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum PhotoKind {
    Image,
    Video,
    Raw,
}

/// RAW formats are indexed + embedded-preview only (§4.5, §6.9).
pub fn is_raw_ext(ext: &str) -> bool {
    matches!(
        ext.to_ascii_lowercase().as_str(),
        "cr2" | "cr3" | "nef" | "arw" | "dng" | "orf" | "rw2" | "raf" | "pef" | "srw" | "x3f"
            | "3fr" | "fff" | "rwl" | "raw"
    )
}

/// §8.2 + §4.5 kind table.
pub fn classify(ext: &str) -> Option<PhotoKind> {
    let e = ext.to_ascii_lowercase();
    if is_raw_ext(&e) {
        return Some(PhotoKind::Raw);
    }
    match e.as_str() {
        "jpg" | "jpeg" | "jfif" | "png" | "webp" | "gif" | "bmp" | "tif" | "tiff" | "avif"
        | "jxl" | "qoi" | "tga" | "ico" | "ppm" | "pgm" | "pnm" | "pam" | "ff" | "heic"
        | "heif" | "svg" => Some(PhotoKind::Image),
        "mp4" | "mkv" | "webm" | "mov" | "avi" | "m4v" | "mpg" | "mpeg" => Some(PhotoKind::Video),
        // `.xmp` is never a photo — it binds to its base image.
        _ => None,
    }
}

/// F9 `photo_id`: BLAKE3 over device ‖ inode. The path is excluded (rename-safe).
pub fn photo_id(dev: u64, inode: u64) -> PhotoId {
    let mut h = Hasher::new();
    h.update(&dev.to_le_bytes());
    h.update(&inode.to_le_bytes());
    let d = h.finalize();
    let mut id = [0u8; 16];
    id.copy_from_slice(&d.as_bytes()[..16]);
    id
}

/// Fallback identity when the platform exposes no inode (zeros still hash).
pub fn photo_id_of_path(path: &str, mtime_ns: i64) -> PhotoId {
    let mut h = Hasher::new();
    h.update(path.as_bytes());
    h.update(&mtime_ns.to_le_bytes());
    let d = h.finalize();
    let mut id = [0u8; 16];
    id.copy_from_slice(&d.as_bytes()[..16]);
    id
}

/// Where `taken_at` came from — the info panel shows the sentence (§8.3).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum TakenSource {
    ExifOriginal,
    ExifDigitized,
    Exif,
    Filename,
    Container,
    FileModified,
    Unknown,
}

impl TakenSource {
    pub fn sentence(&self) -> &'static str {
        match self {
            TakenSource::ExifOriginal => "EXIF DateTimeOriginal",
            TakenSource::ExifDigitized => "EXIF DateTimeDigitized",
            TakenSource::Exif => "EXIF DateTime",
            TakenSource::Filename => "filename",
            TakenSource::Container => "container",
            TakenSource::FileModified => "file modified time",
            TakenSource::Unknown => "unknown",
        }
    }
}

/// The indexed photo record (§8.7). No field without a consumer.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct PhotoRecord {
    pub id: PhotoId,
    pub path: String,
    pub name: String,
    pub kind: PhotoKind,
    pub size: u64,
    pub mtime_ns: i64,
    /// Oriented dimensions (EXIF rotation applied via [`crate::exif::oriented`]).
    pub dims: (u32, u32),
    pub taken_at: Option<i64>,
    pub taken_source: TakenSource,
    pub rating: u8,
    pub favourite: bool,
    pub tags: Vec<String>,
    pub caption: String,
    pub title: String,
    pub gps: Option<(f64, f64, Option<f64>)>,
    pub camera: String,
    pub dominant: [u8; 3],
    pub hash256k: String,
    pub available: bool,
    pub missing_since: Option<i64>,
    pub edit_generation: u64,
}

impl PhotoRecord {
    pub fn new(id: PhotoId, path: String, kind: PhotoKind) -> Self {
        let name = path.rsplit('/').next().unwrap_or(&path).to_string();
        Self {
            id,
            path,
            name,
            kind,
            size: 0,
            mtime_ns: 0,
            dims: (0, 0),
            taken_at: None,
            taken_source: TakenSource::Unknown,
            rating: 0,
            favourite: false,
            tags: Vec::new(),
            caption: String::new(),
            title: String::new(),
            gps: None,
            camera: String::new(),
            dominant: [0, 0, 0],
            hash256k: String::new(),
            available: true,
            missing_since: None,
            edit_generation: 0,
        }
    }
}

