//! Protocol-first gateways (PHOTOS-SPECS §5).
//!
//! The app depends on these traits, never on a backend. A Linux, Android or
//! iOS backend implements them over the `smart-protocol-rs` domains:
//! Files (`domain-files`), Media (`domain-media`), Storage (`domain-storage`)
//! and Camera (`domain-camera`). Backends are disposable; the wire contract
//! is the `.capnp` schema under `../../protocol/`.

use std::path::PathBuf;

/// `domain-files`: list / stat / read / write / rename / mkdir / watch.
/// Bounded `DataHandle` pulls (file + offset + len) instead of whole-file reads.
pub trait FileGateway: Send + Sync {
    /// Paginated, bounded listing (max-depth, max-entries).
    fn list_dir(&self, dir: &str, max: usize) -> Vec<FileStat>;
    fn stat(&self, path: &str) -> Option<FileStat>;
    /// Bounded read: at most `max_bytes` starting at `offset`.
    fn read_range(&self, path: &str, offset: u64, max_bytes: usize) -> Option<Vec<u8>>;
    fn create_file(&self, path: &str, bytes: &[u8]) -> Result<(), String>;
    fn rename(&self, from: &str, to: &str) -> Result<(), String>;
    fn mkdir(&self, path: &str) -> Result<(), String>;
    fn exists(&self, path: &str) -> bool {
        self.stat(path).is_some()
    }
}

/// `domain-media`: MediaItem (contentHash), aiTags, supported formats, export.
pub trait MediaGateway: Send + Sync {
    fn content_hash(&self, path: &str) -> Option<String>;
    fn supported_formats(&self) -> Vec<&'static str>;
    fn export(&self, src: &str, dest: &str, quality: u8) -> Result<(), String>;
}

/// `domain-storage`: volumes that Photos scans (read-only consumers only).
pub trait StorageGateway: Send + Sync {
    fn volumes(&self) -> Vec<Volume>;
}

/// `domain-camera`: capturePhoto + detectFaces + getRichMetadata.
pub trait CameraGateway: Send + Sync {
    fn capture_photo(&self, opts: &CaptureOptions) -> Result<String, String>;
    fn probe_available(&self) -> Result<(), String>;
}

#[derive(Clone, Debug)]
pub struct FileStat {
    pub path: String,
    pub name: String,
    pub size: u64,
    pub mtime_ns: i64,
    pub is_dir: bool,
    pub dev: u64,
    pub inode: u64,
}

#[derive(Clone, Debug)]
pub struct Volume {
    pub path: String,
    pub removable: bool,
    pub read_only: bool,
    pub watched: bool,
    pub last_count: usize,
}

#[derive(Clone, Debug, Default)]
pub struct CaptureOptions {
    pub format: String,
    pub hdr: bool,
    pub filter: Option<String>,
}

/// Honest filesystem gateway over a local root. Swap it for ADB/MTP/PhotoKit
/// without recompiling the UI. Reads are bounded; the image bytes are never
/// modified by the editor (§7) — writes only land via Export/trash paths.
#[derive(Debug, Default)]
pub struct LocalGateway {
    pub roots: Vec<PathBuf>,
}

impl LocalGateway {
    pub fn with_roots(roots: Vec<PathBuf>) -> Self {
        Self { roots }
    }
    fn real(&self, path: &str) -> PathBuf {
        let p = PathBuf::from(path);
        if p.is_absolute() {
            p
        } else if let Some(r) = self.roots.first() {
            r.join(p)
        } else {
            p
        }
    }
}

impl FileGateway for LocalGateway {
    fn list_dir(&self, dir: &str, max: usize) -> Vec<FileStat> {
        let mut out = Vec::new();
        let d = self.real(dir);
        if let Ok(rd) = std::fs::read_dir(&d) {
            for e in rd.flatten().take(max) {
                let p = e.path();
                if let Ok(m) = e.metadata() {
                    #[cfg(unix)]
                    let (dev, inode) = {
                        use std::os::unix::fs::MetadataExt;
                        (m.dev(), m.ino())
                    };
                    #[cfg(not(unix))]
                    let (dev, inode) = (0u64, 0u64);
                    out.push(FileStat {
                        name: e.file_name().to_string_lossy().to_string(),
                        path: p.to_string_lossy().to_string(),
                        size: m.len(),
                        mtime_ns: m
                            .modified()
                            .ok()
                            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                            .map(|d| d.as_nanos() as i64)
                            .unwrap_or(0),
                        is_dir: m.is_dir(),
                        dev,
                        inode,
                    });
                }
            }
        }
        out
    }

    fn stat(&self, path: &str) -> Option<FileStat> {
        let m = std::fs::metadata(self.real(path)).ok()?;
        #[cfg(unix)]
        let (dev, inode) = {
            use std::os::unix::fs::MetadataExt;
            (m.dev(), m.ino())
        };
        #[cfg(not(unix))]
        let (dev, inode) = (0u64, 0u64);
        Some(FileStat {
            path: path.to_string(),
            name: path.rsplit('/').next().unwrap_or(path).to_string(),
            size: m.len(),
            mtime_ns: m
                .modified()
                .ok()
                .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|d| d.as_nanos() as i64)
                .unwrap_or(0),
            is_dir: m.is_dir(),
            dev,
            inode,
        })
    }

    fn read_range(&self, path: &str, offset: u64, max_bytes: usize) -> Option<Vec<u8>> {
        let real = self.real(path);
        let mut f = std::fs::File::open(real).ok()?;
        use std::io::{Read, Seek, SeekFrom};
        f.seek(SeekFrom::Start(offset)).ok()?;
        let mut buf = vec![0u8; max_bytes];
        let n = f.read(&mut buf).ok()?;
        buf.truncate(n);
        Some(buf)
    }

    fn create_file(&self, path: &str, bytes: &[u8]) -> Result<(), String> {
        let real = self.real(path);
        if let Some(parent) = real.parent() {
            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
        std::fs::write(&real, bytes).map_err(|e| e.to_string())
    }

    fn rename(&self, from: &str, to: &str) -> Result<(), String> {
        let a = self.real(from);
        let b = self.real(to);
        if let Some(parent) = b.parent() {
            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
        std::fs::rename(&a, &b).map_err(|e| e.to_string())
    }

    fn mkdir(&self, path: &str) -> Result<(), String> {
        std::fs::create_dir_all(self.real(path)).map_err(|e| e.to_string())
    }
}

impl StorageGateway for LocalGateway {
    fn volumes(&self) -> Vec<Volume> {
        self.roots
            .iter()
            .map(|r| Volume {
                path: r.to_string_lossy().to_string(),
                removable: false,
                read_only: false,
                watched: true,
                last_count: 0,
            })
            .collect()
    }
}

impl MediaGateway for LocalGateway {
    fn content_hash(&self, path: &str) -> Option<String> {
        let bytes = self.read_range(path, 0, 256 << 10)?;
        Some(blake3::hash(&bytes).to_string())
    }
    fn supported_formats(&self) -> Vec<&'static str> {
        vec!["jpeg", "png"]
    }
    fn export(&self, src: &str, dest: &str, _quality: u8) -> Result<(), String> {
        // Local export is a byte copy; pixel baking happens in `editor` +
        // `image` in a worker, never on the UI thread (§4.8).
        let bytes = self.read_range(src, 0, usize::MAX).ok_or("cannot read source")?;
        self.create_file(dest, &bytes)
    }
}

