    #[test]
    fn key_changes_with_mtime_orientation_and_generation() {
        let a = cache_key("/p/a.jpg", 256, 100, 1, 0);
        assert_ne!(a, cache_key("/p/a.jpg", 256, 200, 1, 0), "mtime must be in the key");
        assert_ne!(a, cache_key("/p/a.jpg", 256, 100, 6, 0), "orientation must be in the key");
        assert_ne!(a, cache_key("/p/a.jpg", 256, 100, 1, 1), "edit_generation must be in the key");
        assert_ne!(a, cache_key("/p/a.jpg", 512, 100, 1, 0), "rung must be in the key");
