        assert_eq!(wanted_rung(60.0), 64);
        assert_eq!(wanted_rung(100.0), 128);
        assert!(wanted_rung(300.0) <= 512);
        assert_eq!(wanted_rung(99999.0), 4096);
    }

    #[test]
    fn big_pool_is_bounded_at_eight() {
        let mut pool: BigPool = Lru::new(8);
        for i in 0..20 {
            pool.insert(format!("k{i}"), vec![0u8; 4]);
        }
        assert_eq!(pool.len(), 8);
    }

    #[test]
    fn lru_evicts_least_recently_seen() {
        let mut c: Lru<u8> = Lru::new(2);
        c.insert("a".into(), 1);
        c.insert("b".into(), 2);
        let _ = c.get("a"); // a is now most-recently seen
        c.insert("c".into(), 3);
        assert!(c.get("b").is_none());
        assert!(c.get("a").is_some());
    }

    #[test]
    fn fanout_is_2_2() {
        let (a, b) = fanout("a1b2c3");
        assert_eq!((a.as_str(), b.as_str()), ("a1", "b2"));
    }
}

//! Editor — non-destructive, sidecar-backed, reversible (PHOTOS-SPECS §7).
//!
//! The image bytes are never modified. Pixels are baked only on Export.
//! `process()` is the CPU per-pixel adjustment (exposure `2^e`, contrast,
//! luma-based saturation + warmth, smoothstep vignette) run on a ≤1024 px
//! proxy in the UI beat; full-res runs debounced in a worker (§4.8).
//! RAW/HEIC/AVIF decoding: the `image` crate ships png/jpeg only, so those
//! kinds return `None` and surface as a declared "indexed — preview
//! unavailable" state (§4.5), never a black tile.

use image::{GenericImageView, RgbImage};
use serde::{Deserialize, Serialize};

/// Full adjust set (the 5 egui sliders + 5 more per §7.3).
#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
pub struct Adjust {
    pub exposure: f32,
    pub contrast: f32,
    pub saturation: f32,
    pub warmth: f32,
    pub vignette: f32,
    pub blacks: f32,
    pub whites: f32,
    pub clarity: f32,
    pub texture: f32,
    pub dehaze: f32,
}

impl Default for Adjust {
    fn default() -> Self {
        Self {
            exposure: 0.0, contrast: 0.0, saturation: 0.0, warmth: 0.0, vignette: 0.0,
            blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0,
        }
    }
}

/// Named recipes — the 8 F1 presets (values verbatim from `photos.rs`).
pub const PRESETS: [(&str, Adjust); 8] = [
    ("Original", Adjust { exposure: 0.0, contrast: 0.0, saturation: 0.0, warmth: 0.0, vignette: 0.0, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
    ("Vivid", Adjust { exposure: 0.05, contrast: 0.18, saturation: 0.45, warmth: 0.05, vignette: 0.0, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
    ("Warm", Adjust { exposure: 0.05, contrast: 0.05, saturation: 0.10, warmth: 0.55, vignette: 0.10, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
    ("Cool", Adjust { exposure: 0.0, contrast: 0.08, saturation: 0.0, warmth: -0.55, vignette: 0.10, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
    ("Mono", Adjust { exposure: 0.0, contrast: 0.12, saturation: -1.0, warmth: 0.0, vignette: 0.0, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
    ("Noir", Adjust { exposure: -0.10, contrast: 0.40, saturation: -1.0, warmth: 0.0, vignette: 0.55, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
    ("Fade", Adjust { exposure: 0.15, contrast: -0.25, saturation: -0.30, warmth: 0.10, vignette: 0.0, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
    ("Dusk", Adjust { exposure: -0.10, contrast: 0.15, saturation: 0.20, warmth: -0.25, vignette: 0.40, blacks: 0.0, whites: 0.0, clarity: 0.0, texture: 0.0, dehaze: 0.0 }),
];

/// CPU per-pixel process on an RGB image. Pure and testable.
pub fn process(src: &[u8], w: u32, h: u32, adj: &Adjust) -> Vec<u8> {
    let mut out = vec![0u8; src.len()];
    let exp = 2f32.powf(adj.exposure);
    let con = adj.contrast;
    let sat = adj.saturation;
    let warm = adj.warmth;
    let vig = adj.vignette;
    for i in 0..(w * h) as usize {
        let r = src[..][i * 3] as f32 / 255.0;
        let g = src[..][i * 3 + 1] as f32 / 255.0;
        let b = src[..][i * 3 + 2] as f32 / 255.0;
        let luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        let mix = |c: f32| (luma + (c - luma) * (1.0 + sat)).clamp(0.0, 1.0);
        let c1 = mix(r) * exp;
        let c2 = mix(g) * exp;
        let c3 = mix(b) * exp;
        let cc = |v: f32| ((v - 0.5) * (1.0 + con) + 0.5).clamp(0.0, 1.0);
        let mut nr = cc(c1 + warm * 0.10);
        let mut ng = cc(c2);
        let mut nb = cc(c3 - warm * 0.10);
        if vig.abs() > f32::EPSILON {
            let x = (i as u32 % w) as f32 / (w.max(1) as f32);
            let y = (i as u32 / w) as f32 / (h.max(1) as f32);
            let dx = x - 0.5;
            let dy = y - 0.5;
            let d = (dx * dx + dy * dy) * 4.0;
            let s = (d * d - 0.5 * d + 1.0).clamp(0.0, 1.0);
            let k = 1.0 - vig * s * 0.6;
            nr *= k;
            ng *= k;
            nb *= k;
        }
        out[i * 3] = (nr * 255.0).round() as u8;
        out[i * 3 + 1] = (ng * 255.0).round() as u8;
        out[i * 3 + 2] = (nb * 255.0).round() as u8;
    }
    out
}

/// Aspect presets for crop (1:1 / 4:3 / 3:2 / 16:9 / 4:5 + free).
pub fn crop_rect(w: u32, h: u32, aspect: Option<(f32, f32)>) -> (u32, u32, u32, u32) {
    if let Some((aw, ah)) = aspect {
        let target = aw / ah;
        let ratio = w as f32 / h as f32;
        let (cw, ch) = if ratio > target { ((h as f32 * target) as u32, h) } else { (w, (w as f32 / target) as u32) };
        ((w - cw) / 2, (h - ch) / 2, cw, ch)
    } else {
        (0, 0, w, h)
    }
}

/// Decode bytes to RGB with the `image` crate (png/jpeg only).
/// Returns `None` for undecodable formats — the caller declares the honest
/// "indexed, no preview" state (RAW/HEIC/AVIF/TIFF without a decoder).
pub fn decode(bytes: &[u8]) -> Option<(RgbImage, (u32, u32))> {
    let img = image::load_from_memory(bytes).ok()?;
    let dims = img.dimensions();
    Some((img.to_rgb8(), dims))
}

/// One reversible operation: the *before image* + the forward path, never a
/// bespoke inverse. An `Operation` is inverted by writing the before-image
/// back through the same path that produced it (§7.4).
#[derive(Clone, Debug)]
pub struct Operation {
    pub label: String,
    pub before: String,
    pub after: String,
    pub target: String,
}

/// One editor/sidecar/organise action (command-index ids, Appendix A).
#[derive(Clone, Debug)]
pub enum EditOp {
    Adjust { target: String, before: Adjust, after: Adjust },
    Crop { target: String, before: String, after: String },
    Rotate { target: String, before: i32, after: i32 },
    FlipH { target: String },
    FlipV { target: String },
    Filter { target: String, before: String, after: String },
    Rating { target: String, before: u8, after: u8 },
    Favourite { target: String, before: bool, after: bool },
    Tag { target: String, before: Vec<String>, after: Vec<String> },
    Caption { target: String, before: String, after: String },
    Trash { target: String },
    Export { target: String, written: Vec<String> },
    Reset { target: String },
}

impl EditOp {
    pub fn label(&self) -> String {
        match self {
            EditOp::Adjust { .. } => "Adjust".into(),
            EditOp::Crop { .. } => "Crop".into(),
            EditOp::Rotate { .. } => "Rotate".into(),
            EditOp::FlipH { .. } => "Flip horizontal".into(),
            EditOp::FlipV { .. } => "Flip vertical".into(),
            EditOp::Filter { .. } => "Filter".into(),
            EditOp::Rating { .. } => "Rating".into(),
            EditOp::Favourite { .. } => "Favourite".into(),
            EditOp::Tag { .. } => "Tags".into(),
            EditOp::Caption { .. } => "Caption".into(),
            EditOp::Trash { .. } => "Move to Trash".into(),
            EditOp::Export { .. } => "Export".into(),
            EditOp::Reset { .. } => "Reset all edits".into(),
        }
    }
    fn target(&self) -> &str {
        match self {
            EditOp::Adjust { target, .. } => target,
            EditOp::Crop { target, .. } => target,
            EditOp::Rotate { target, .. } => target,
            EditOp::FlipH { target } => target,
            EditOp::FlipV { target } => target,
            EditOp::Filter { target, .. } => target,
            EditOp::Rating { target, .. } => target,
            EditOp::Favourite { target, .. } => target,
            EditOp::Tag { target, .. } => target,
            EditOp::Caption { target, .. } => target,
            EditOp::Trash { target } => target,
            EditOp::Export { target, .. } => target,
            EditOp::Reset { target } => target,
        }
    }
}

pub const UNDO_DEPTH: usize = 100;

/// The user-visible history (last 20, labelled in the user's words, §7.4).
#[derive(Debug, Default)]
pub struct UndoLog {
    depth: usize,
    done: Vec<Operation>,
    undone: Vec<Operation>,
}

impl UndoLog {
    pub fn new(depth: usize) -> Self {
        Self { depth: depth.max(1), done: Vec::new(), undone: Vec::new() }
    }
    pub fn apply(&mut self, op: EditOp) {
        let (before, after) = match &op {
            EditOp::Adjust { before, after, .. } => {
                (serde_json::to_string(before).unwrap_or_default(), serde_json::to_string(after).unwrap_or_default())
            }
            EditOp::Crop { before, after, .. } => (before.clone(), after.clone()),
            EditOp::Rotate { before, after, .. } => (before.to_string(), after.to_string()),
            EditOp::Filter { before, after, .. } => (before.clone(), after.clone()),
            EditOp::Rating { before, after, .. } => (before.to_string(), after.to_string()),
            EditOp::Favourite { before, after, .. } => (before.to_string(), after.to_string()),
            EditOp::Tag { before, after, .. } => (serde_json::to_string(before).unwrap_or_default(), serde_json::to_string(after).unwrap_or_default()),
            EditOp::Caption { before, after, .. } => (before.clone(), after.clone()),
            EditOp::Trash { target } => ("present".into(), format!("trashed:{target}")),
            EditOp::Export { written, .. } => ("none".into(), written.join(",")),
            EditOp::FlipH { .. } | EditOp::FlipV { .. } | EditOp::Reset { .. } => ("old".into(), "new".into()),
        };
        let operation = Operation { label: op.label(), before, after, target: op.target().to_string() };
        self.undone.clear();
        self.done.push(operation);
        while self.done.len() > self.depth {
            self.done.remove(0);
        }
    }
    pub fn can_undo(&self) -> bool {
        !self.done.is_empty()
    }
    pub fn can_redo(&self) -> bool {
        !self.undone.is_empty()
    }
    /// Invert one operation — the caller writes the before-image back through
    /// the same path. Returns the operation that was undone.
    pub fn undo(&mut self) -> Option<Operation> {
        let op = self.done.pop()?;
        self.undone.push(op.clone());
        Some(op)
    }
    pub fn redo(&mut self) -> Option<Operation> {
        let op = self.undone.pop()?;
        self.done.push(op.clone());
        Some(op)
    }
    /// Last 20, labelled in the user's words (§7.4).
    pub fn history(&self) -> Vec<String> {
        self.done.iter().rev().take(20).map(|o| format!("{} — {}", o.label, o.target)).collect()
    }
    pub fn len(&self) -> usize {
        self.done.len()
    }
    pub fn is_empty(&self) -> bool {
        self.done.is_empty()
    }
}

/// Export naming law (§7.5): `<name> (Edited).<ext>` — never overwrite.
/// Returns the first free name (` (Edited)`, ` (Edited 2)`, …).
pub fn export_name(dir: &str, stem: &str, ext: &str, exists: impl Fn(&str) -> bool) -> String {
    let mut n = 0usize;
    loop {
        let suffix = if n == 0 { " (Edited)".to_string() } else { format!(" (Edited {})", n + 1) };
        let candidate = format!("{}/{}{}.{}", dir, stem, suffix, ext);
        if !exists(&candidate) {
            return candidate;
        }
        n += 1;
    }
}

