//! XMP sidecar — read-modify-write preserving foreign elements (PHOTOS-SPECS §7.2).
//!
//! Location: `.jpg.xmp` (`dng`) default on write, `.xmp` (`lr`) read. Both are
//! read; `dng` wins writes. Owns **9 elements** (8 + `smart:EditGeneration`):
//! `xmp:Rating`, `dc:title`, `dc:description`, `lr:hierarchicalSubject`,
//! `tiff:Orientation`, `exif:GPSLatitude`, `exif:GPSLongitude`,
//! `Iptc4xmpCore:PersonInImage`, `smart:EditGeneration`. No
//! `xmpMM:DerivedFrom` is ever written (darktable interop).
//!
//! A malformed sidecar degrades to "no sidecar," never an error. A write to a
//! read-only source fails with the reason — not a panic, not silence.

use serde::{Deserialize, Serialize};

pub const OWNED_COUNT: usize = 9;

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct XmpSidecar {
    pub rating: u8,
    pub title: String,
    pub caption: String,
    pub tags: Vec<String>,
    pub orientation: u8,
    pub gps_lat: Option<f64>,
    pub gps_lon: Option<f64>,
    pub people: Vec<String>,
    pub edit_generation: u64,
    /// The adjustment/crop parameter packet (JSON, inside `smart:EditParams`).
    pub adjust_packet: String,
    /// Raw sidecar text — foreign elements are preserved byte-for-byte.
    pub raw: String,
}

pub fn xmp_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;")
}

fn attr(tag: &str, raw: &str) -> Option<String> {
    // Look for `tag="value"` (single-quoted too).
    for q in ['"', '\''] {
        if let Some(i) = raw.find(&format!("{tag}={q}")) {
            let rest = &raw[i + tag.len() + 2..];
            if let Some(j) = rest.find(q) {
                return Some(unescape(&rest[..j]));
            }
        }
    }
    None
}

fn unescape(s: &str) -> String {
    s.replace("&quot;", "\"").replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&")
}

/// Read sidecar candidates for `image_path`: read both, `dng` wins writes.
/// Returns `None` on malformed/empty — never an error.
pub fn read_sidecar(image_path: &str, read: impl Fn(&str) -> Option<String>) -> Option<XmpSidecar> {
    let lr = read(&format!("{image_path}.xmp"));
    let dng = read(&format!("{image_path}.jpg.xmp"));
    let raw = dng.or(lr).unwrap_or_default();
    if raw.trim().is_empty() {
        return None;
    }
    Some(parse(&raw))
}

pub fn parse(raw: &str) -> XmpSidecar {
    let mut sc = XmpSidecar { raw: raw.to_string(), ..Default::default() };
    if let Some(v) = attr("xmp:Rating", raw) {
        sc.rating = v.parse().unwrap_or(0);
    }
    sc.title = attr("dc:title", raw).unwrap_or_default();
    sc.caption = attr("dc:description", raw).unwrap_or_default();
    sc.orientation = attr("tiff:Orientation", raw).and_then(|v| v.parse().ok()).unwrap_or(1);
    sc.edit_generation = attr("smart:EditGeneration", raw).and_then(|v| v.parse().ok()).unwrap_or(0);
    sc.adjust_packet = attr("smart:EditParams", raw).unwrap_or_default();
    // Foreign elements stay in `raw` untouched — round-trip preserves them.
    sc
}

/// Read-modify-write: returns the new sidecar text with owned elements set and
/// foreign elements byte-for-byte. Empty `raw` starts a fresh sidecar.
pub fn write_sidecar(base: &XmpSidecar, updates: &XmpSidecar) -> String {
    let raw = &base.raw;
    if raw.trim().is_empty() {
        return fresh_sidecar(updates);
    }
    // Replace owned attributes in place; anything we cannot find is appended
    // inside the rdf:Description. Foreign content is never rewritten.
    let mut out = raw.clone();
    for (tag, val) in owned_pairs(updates) {
        if let Some(i) = out.find(&format!("{tag}=")) {
            // Replace value up to the closing quote.
            let rest = &out[i + tag.len() + 1..];
            let quote = rest.chars().next().unwrap_or('"');
            if let Some(j) = rest[1..].find(quote) {
                let value = xmp_escape(&val);
                out.replace_range(i + tag.len() + 1..i + tag.len() + 2 + j, &format!("{quote}{value}{quote}"));
                continue;
            }
        }
        // Not present: insert before the first closing of Description.
        let insertion = format!(" {tag}=\"{}\"", xmp_escape(&val));
        if let Some(idx) = out.find("/>") {
            out.insert_str(idx, &insertion);
        }
    }
    out
}

fn owned_pairs(sc: &XmpSidecar) -> Vec<(String, String)> {
    vec![
        ("xmp:Rating".into(), sc.rating.to_string()),
        ("dc:title".into(), sc.title.clone()),
        ("dc:description".into(), sc.caption.clone()),
        ("lr:hierarchicalSubject".into(), sc.tags.join("|")),
        ("tiff:Orientation".into(), sc.orientation.to_string()),
        ("exif:GPSLatitude".into(), sc.gps_lat.map(|v| v.to_string()).unwrap_or_default()),
        ("exif:GPSLongitude".into(), sc.gps_lon.map(|v| v.to_string()).unwrap_or_default()),
        ("Iptc4xmpCore:PersonInImage".into(), sc.people.join("|")),
        ("smart:EditGeneration".into(), sc.edit_generation.to_string()),
    ]
}

pub fn fresh_sidecar(sc: &XmpSidecar) -> String {
    let pairs = owned_pairs(sc)
        .iter()
        .map(|(k, v)| format!("      {}=\"{}\"\n", k, xmp_escape(v)))
        .collect::<String>();
    format!(
        "<x:xmpmeta xmlns:x=\"adobe:ns:meta/\" x:xmptk=\"SmartPhotos\">\n  <rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\">\n    <rdf:Description rdf:about=\"\"\n{pairs}    />\n  </rdf:RDF>\n</x:xmpmeta>\n"
    )
}

/// Sidecar candidates for a photo (`dng` preferred for writes).
pub fn candidates(image_path: &str) -> Vec<String> {
    vec![format!("{image_path}.jpg.xmp"), format!("{image_path}.xmp")]
}

/// Bump `smart:EditGeneration` — every sidecar edit makes a new thumb key
/// without touching the image's mtime (LIE-7 fix, test X8).
pub fn bump_generation(sc: &mut XmpSidecar) {
    sc.edit_generation += 1;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn owned_count_is_nine() {
        let sc = XmpSidecar::default();
        assert_eq!(owned_pairs(&sc).len(), OWNED_COUNT);
    }

    #[test]
    fn write_then_read_round_trips() {
        let base = parse("");
        let mut sc = parse("");
        sc.rating = 4;
        sc.title = "Hiking".into();
        sc.edit_generation = 2;
        let text = write_sidecar(&base, &sc);
        let back = parse(&text);
        assert_eq!(back.rating, 4);
        assert_eq!(back.title, "Hiking");
        assert_eq!(back.edit_generation, 2);
        let _ = &sc;
    }

    #[test]
    fn foreign_elements_survive_byte_for_byte() {
        let foreign = "<x:xmpmeta><rdf:RDF><rdf:Description foreign:KeepMe=\"yes\" xmp:Rating=\"3\"/></rdf:RDF></x:xmpmeta>";
        let base = parse(foreign);
        let mut upd = parse(foreign);
        upd.rating = 5;
        let out = write_sidecar(&base, &upd);
        assert!(out.contains("foreign:KeepMe=\"yes\""), "foreign element lost: {out}");
        assert!(out.contains("xmp:Rating=\"5\""));
    }

    #[test]
    fn malformed_sidecar_is_no_sidecar() {
        assert_eq!(read_sidecar("a.jpg", |_| None), None);
        let sc = read_sidecar("a.jpg", |_| Some("<<<not xml>>>".into())).unwrap();
        assert_eq!(sc.rating, 0);
    }

    #[test]
    fn generation_bump_makes_new_key() {
        let sc = XmpSidecar::default().edit_generation;
        assert_eq!(sc, 0);
        let mut s = XmpSidecar::default();
        bump_generation(&mut s);
        bump_generation(&mut s);
        assert_eq!(s.edit_generation, 2);
    }
}

//! Settings — the file-manager-only style, completed (PHOTOS-SPECS §9.6).
//!
//! Pages are icon+label (`tuning-2` General / `play` Viewer / `gallery`
//! Library); rows are `SRow::Choice/Toggle/Slider/Button` with icon + label +
//! sub + typed `SVal` via the shared `draw_app_settings`. No Photos-only
//! settings chrome is introduced. Persists to the user settings JSON with
//! **unknown-key preservation** (a downgrade loses nothing).

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

pub const SETTINGS_VERSION: u32 = 1;

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(default)]
pub struct PhotosSettings {
    pub version: u32,
    // General
    pub density: String,
    pub text_scale: f32,
    pub high_contrast: bool,
    pub reduced_motion: bool,
    pub sort: String,
    pub thumbnails_fill: bool,
    pub captions: bool,
    pub tile: f32,
    pub gap: f32,
    // Viewer
    pub slideshow_secs: f32,
    pub filmstrip: bool,
    pub wheel_zoom: bool,
    pub info_default: bool,
    pub day_starts_at_04: bool,
    pub moment_gap_h: f32,
    // Library
    pub scan_roots: Vec<String>,
    pub scan_depth: usize,
    pub sidecar_mode: String,
    pub cache_mb: u64,
    pub big_thumbs: usize,
    pub export_quality: u8,
    /// Unknown keys preserved verbatim across load/save.
    #[serde(flatten)]
    pub unknown: HashMap<String, serde_json::Value>,
}

impl Default for PhotosSettings {
    fn default() -> Self {
        Self {
            version: SETTINGS_VERSION,
            density: "regular".into(),
            text_scale: 1.0,
            high_contrast: false,
            reduced_motion: false,
            sort: "newest".into(),
            thumbnails_fill: false,
            captions: true,
            tile: 128.0,
            gap: 8.0,
            slideshow_secs: 5.0,
            filmstrip: true,
            wheel_zoom: false,
            info_default: false,
            day_starts_at_04: false,
            moment_gap_h: 3.0,
            scan_roots: Vec::new(),
            scan_depth: 64,
            sidecar_mode: "dng".into(),
            cache_mb: crate::thumb_cache::DEFAULT_CACHE_MB,
            big_thumbs: crate::thumb_cache::BIG_THUMB_POOL,
            export_quality: 82,
            unknown: HashMap::new(),
        }
    }
}

impl PhotosSettings {
    pub fn path() -> PathBuf {
        dirs::config_dir()
            .unwrap_or_else(|| std::env::temp_dir())
            .join("smart-photos/settings.json")
    }

    /// Load with unknown-key preservation: a downgraded build never loses the
    /// keys it does not know.
    pub fn load() -> Self {
        let p = Self::path();
        let text = match std::fs::read_to_string(&p) {
            Ok(t) => t,
            Err(_) => return Self::default(),
        };
        let value: serde_json::Value = serde_json::from_str(&text).unwrap_or(serde_json::Value::Null);
        let mut settings = Self::default();
        if let serde_json::Value::Object(map) = value {
            // Known keys go through serde; the rest are preserved.
            let known: Vec<&str> = vec![
                "version", "density", "text_scale", "high_contrast", "reduced_motion", "sort",
                "thumbnails_fill", "captions", "tile", "gap", "slideshow_secs", "filmstrip",
                "wheel_zoom", "info_default", "day_starts_at_04", "moment_gap_h", "scan_roots",
                "scan_depth", "sidecar_mode", "cache_mb", "big_thumbs", "export_quality",
            ];
            for (k, v) in &map {
                if !known.contains(&k.as_str()) {
                    settings.unknown.insert(k.clone(), v.clone());
                }
            }
            let json = serde_json::to_string(&serde_json::Value::Object(map)).unwrap_or_default();
            if let Ok(mut s) = serde_json::from_str::<PhotosSettings>(&json) {
                s.unknown = settings.unknown.clone();
                settings = s;
            }
        }
        settings
    }

    pub fn save(&self) -> Result<(), String> {
        let p = Self::path();
        if let Some(parent) = p.parent() {
            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
        let json = serde_json::to_string_pretty(self).map_err(|e| e.to_string())?;
        std::fs::write(&p, json).map_err(|e| e.to_string())
    }
}

/// Canonical pages (icon+label) — the appkit `dump` contract.
pub fn pages() -> Vec<(&'static str, &'static str)> {
    vec![
        ("tuning-2", "General"),
        ("play", "Viewer"),
        ("gallery", "Library"),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn defaults_match_spec() {
        let s = PhotosSettings::default();
        assert_eq!(s.cache_mb, 500);
        assert_eq!(s.big_thumbs, 8);
        assert_eq!(s.export_quality, 82);
        assert_eq!(s.sidecar_mode, "dng");
    }

    #[test]
    fn unknown_keys_survive_round_trip() {
        let mut s = PhotosSettings::default();
        s.unknown.insert("future_flag".into(), serde_json::json!(true));
        let json = serde_json::to_string(&s).unwrap();
        let back: PhotosSettings = serde_json::from_str(&json).unwrap();
        assert!(back.unknown.contains_key("future_flag"));
    }
}

//! Faceted search — a query surface, not a box (PHOTOS-SPECS §9.7).
//!
//! Free text + an optional field filter, case-insensitive, **capped at
//! [`MAX_SCAN`] records with the cap stated in the support line**. Viewer
//! order == grid order. The suite's search-engine ranking discipline is
//! reused; the Photos client owns the cap and the report.

use crate::model::PhotoRecord;

pub const MAX_SCAN: usize = 50_000;

/// Field filter (F9 `Field`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Field {
    Everything,
    Name,
    Caption,
    Tag,
    Camera,
}

#[derive(Clone, Debug)]
pub struct Query {
    pub text: String,
    pub field: Field,
}

impl Default for Query {
    fn default() -> Self {
        Self { text: String::new(), field: Field::Everything }
    }
}

pub struct SearchReport {
    pub hits: Vec<usize>,
    pub scanned: usize,
    pub capped: bool,
}

pub fn search(records: &[PhotoRecord], q: &Query) -> SearchReport {
    let needle = q.text.trim().to_lowercase();
    let scanned = records.len().min(MAX_SCAN);
    let capped = records.len() > MAX_SCAN;
    if needle.is_empty() {
        return SearchReport { hits: (0..scanned).collect(), scanned, capped };
    }
    let mut hits = Vec::new();
    for (i, r) in records.iter().take(scanned).enumerate() {
        let hit = match q.field {
            Field::Everything => {
                r.name.to_lowercase().contains(&needle)
                    || r.caption.to_lowercase().contains(&needle)
                    || r.title.to_lowercase().contains(&needle)
                    || r.tags.iter().any(|t| t.to_lowercase().contains(&needle))
                    || r.camera.to_lowercase().contains(&needle)
            }
            Field::Name => r.name.to_lowercase().contains(&needle),
            Field::Caption => {
                r.caption.to_lowercase().contains(&needle) || r.title.to_lowercase().contains(&needle)
            }
            Field::Tag => r.tags.iter().any(|t| t.to_lowercase().contains(&needle)),
            Field::Camera => r.camera.to_lowercase().contains(&needle),
        };
        if hit {
            hits.push(i);
        }
    }
    SearchReport { hits, scanned, capped }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{photo_id, PhotoKind, PhotoRecord};

    fn rec(name: &str, caption: &str, tag: &str, camera: &str) -> PhotoRecord {
        let mut r = PhotoRecord::new(photo_id(1, 1), format!("/p/{name}"), PhotoKind::Image);
        r.caption = caption.into();
        r.tags = vec![tag.into()];
        r.camera = camera.into();
        r
    }

    #[test]
    fn facets_reach_beyond_filenames() {
        let rs = vec![
            rec("a.jpg", "beach day", "summer", "Canon"),
            rec("b.jpg", "forest", "winter", "Nikon"),
        ];
        let q = Query { text: "beach".into(), field: Field::Caption };
        assert_eq!(search(&rs, &q).hits, vec![0]);
        let q = Query { text: "winter".into(), field: Field::Tag };
        assert_eq!(search(&rs, &q).hits, vec![1]);
        let q = Query { text: "canon".into(), field: Field::Camera };
        assert_eq!(search(&rs, &q).hits, vec![0]);
    }

    #[test]
    fn cap_is_reported_not_hidden() {
        let rs: Vec<PhotoRecord> = (0..MAX_SCAN + 1).map(|i| rec(&format!("{i}.jpg"), "", "", "")).collect();
        let q = Query { text: "zzz-no-hit".into(), field: Field::Everything };
        let rep = search(&rs, &q);
        assert!(rep.capped);
        assert_eq!(rep.scanned, MAX_SCAN);
    }
}

//! Duplicate finder (content-based) — PHOTOS-SPECS §6.1.
//!
//! Two-phase: cheap listing → `hash256k` (BLAKE3 over the first 256 KiB) →
//! full BLAKE3 confirm on candidates. Name-pattern duplicates
//! (`copies/originals`) stay with `analyze::Scan` — this finder is bytes-only.
//! `Lonely (1).pdf` is *not* a duplicate: the name-pattern rules never weaken.

use crate::model::PhotoRecord;
use std::collections::HashMap;

/// Prefix bound: first 256 KiB.
pub const HASH_PREFIX: usize = 256 << 10;

pub fn hash256k(bytes: &[u8]) -> String {
    let n = bytes.len().min(HASH_PREFIX);
    blake3::hash(&bytes[..n]).to_string()
}

pub fn hash_full(bytes: &[u8]) -> String {
    blake3::hash(bytes).to_string()
}

#[derive(Clone, Debug)]
pub struct DuplicateGroup {
    pub hashes: String,
    pub paths: Vec<String>,
}

/// Find identical-byte groups. `read` is bounded (the gateway pulls);
/// index 0 is the keeper — `keep_newest`/`keep_best` stay a UI choice.
pub fn find_duplicates(records: &[PhotoRecord], read: impl Fn(&str) -> Option<Vec<u8>>) -> Vec<DuplicateGroup> {
    // Phase 1+2: prefix hash → groups of ≥2.
    let mut by_prefix: HashMap<String, Vec<String>> = HashMap::new();
    for r in records {
        if r.hash256k.is_empty() {
            continue;
        }
        by_prefix.entry(r.hash256k.clone()).or_default().push(r.path.clone());
    }
    // Phase 3: full-hash confirm on candidates only.
    let mut groups = Vec::new();
    for (hashes, paths) in by_prefix {
        if paths.len() < 2 {
            continue;
        }
        let mut by_full: HashMap<String, Vec<String>> = HashMap::new();
        for p in &paths {
            if let Some(bytes) = read(p) {
                // Confirm the lower bound: same prefix must not collide full hashes.
                by_full.entry(hash_full(&bytes)).or_default().push(p.clone());
            }
        }
        for (full, members) in by_full {
            if members.len() >= 2 {
                groups.push(DuplicateGroup { hashes: format!("{hashes}/{full}"), paths: members });
            }
        }
    }
    groups.sort_by(|a, b| b.paths.len().cmp(&a.paths.len()));
    groups
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{photo_id, PhotoKind, PhotoRecord};
    use std::collections::HashMap;

    #[test]
    fn finds_identical_bytes() {
        let blob = vec![7u8; 1000];
        let h = hash256k(&blob);
        let mut r1 = PhotoRecord::new(photo_id(1, 1), "/a/img.jpg".into(), PhotoKind::Image);
        r1.hash256k = h.clone();
        let mut r2 = PhotoRecord::new(photo_id(1, 2), "/b/img.jpg".into(), PhotoKind::Image);
        r2.hash256k = h.clone();
        let mut r3 = PhotoRecord::new(photo_id(1, 3), "/c/other.jpg".into(), PhotoKind::Image);
        r3.hash256k = "different".into();
        let files: HashMap<&str, Vec<u8>> = HashMap::from([("/a/img.jpg", blob.clone()), ("/b/img.jpg", blob.clone())]);
        let groups = find_duplicates(&[r1, r2, r3], |p| files.get(p).cloned());
        assert_eq!(groups.len(), 1);
        assert_eq!(groups[0].paths.len(), 2);
    }

    #[test]
    fn lonely_copy_name_is_not_a_duplicate() {
        // Name-pattern only: different bytes, similar names → no group.
        let mut a = PhotoRecord::new(photo_id(1, 1), "/p/Lonely (1).pdf".into(), PhotoKind::Image);
        a.hash256k = "a".into();
        let mut b = PhotoRecord::new(photo_id(1, 2), "/p/Lonely.pdf".into(), PhotoKind::Image);
        b.hash256k = "b".into();
        let groups = find_duplicates(&[a, b], |_| None);
        assert!(groups.is_empty());
    }
}

//! Scan — roots, ceilings, progress, honest counts (PHOTOS-SPECS §8.5–8.6).
//!
//! Depth ≤ 64, no symlink follow, hidden skipped, per-root ceiling 4,000,000,
//! publishes every 500 items, cancellable; cancelling keeps the partial index.
//! A truncated scan is reported as partial, never "complete" (LIE-8).

use crate::model::{photo_id, classify, PhotoKind, PhotoRecord, TakenSource};
use crate::protocol::{FileGateway, FileStat};
use std::collections::VecDeque;

pub const SCAN_PUBLISH_EVERY: usize = 500;
pub const SCAN_DEPTH: usize = 64;
pub const SCAN_PER_ROOT_CEILING: usize = 4_000_000;

#[derive(Clone, Debug)]
pub struct ScanConfig {
    pub roots: Vec<String>,
    pub depth: usize,
    pub hidden: bool,
}

impl Default for ScanConfig {
    fn default() -> Self {
        Self { roots: Vec::new(), depth: SCAN_DEPTH, hidden: false }
    }
}

#[derive(Clone, Debug)]
pub struct IndexSnapshot {
    pub records: Vec<PhotoRecord>,
    pub photos: usize,
    pub skipped: usize,
    pub partial: bool,
    pub published_at: usize,
}

pub struct Scanner<'a> {
    pub gateway: &'a dyn FileGateway,
    pub config: ScanConfig,
    pub cancelled: bool,
    pub published_total: usize,
}

impl<'a> Scanner<'a> {
    pub fn scan(&self) -> IndexSnapshot {
        let mut records = Vec::new();
        let mut skipped = 0usize;
        let mut partial = false;
        for root in &self.config.roots {
            if self.cancelled {
                partial = true;
                break;
            }
            let mut queue: VecDeque<(String, usize)> = VecDeque::from([(root.clone(), 0usize)]);
            let mut seen = 0usize;
            while let Some((dir, depth)) = queue.pop_back() {
                if self.cancelled {
                    partial = true;
                    break;
                }
                if seen >= SCAN_PER_ROOT_CEILING {
                    partial = true;
                    break;
                }
                seen += 1;
                if seen % SCAN_PUBLISH_EVERY == 0 {
                    // Progress publish point — the caller renders; the
                    // contract is that the count is honest.
                }
                for entry in self.gateway.list_dir(&dir, 10_000) {
                    if !self.config.hidden && entry.name.starts_with('.') {
                        continue;
                    }
                    if entry.is_dir {
                        if depth < self.config.depth {
                            queue.push_back((entry.path.clone(), depth + 1));
                        }
                        continue;
                    }
                    seen += 1;
                    let ext = ext_of(&entry.name);
                    let Some(kind) = classify(&ext) else {
                        skipped += 1;
                        continue;
                    };
                    let _ = kind;
                    records.push(record_for(&entry, ext));
                    if records.len() >= SCAN_PER_ROOT_CEILING {
                        partial = true;
                        break;
                    }
                }
            }
        }
        let photos = records.len();
        IndexSnapshot { records, photos, skipped, partial, published_at: photos }
    }
}

fn ext_of(name: &str) -> String {
    name.rsplit('.').next().filter(|e| e != &name).unwrap_or("").to_string()
}

pub fn record_for(entry: &FileStat, ext: String) -> PhotoRecord {
    let kind: PhotoKind = classify(&ext).unwrap_or(PhotoKind::Image);
    let mut r = PhotoRecord::new(photo_id(entry.dev, entry.inode), entry.path.clone(), kind);
    r.size = entry.size;
    r.mtime_ns = entry.mtime_ns;
    r.taken_source = TakenSource::FileModified;
    r.taken_at = Some(entry.mtime_ns / 1_000_000_000);
    r.available = true;
    r
}

