//! Import — MTP honest + local DCIM (PHOTOS-SPECS §6.8).
//!
//! Sources are `read_only + removable` (F9 `Source`): no in-place mutation,
//! explicit "Copy to library". New-file detection is by `contentHash`, and
//! RAW+JPEG pairs (§6.9) group into one tile with a `Stack` badge.
//! Without a registered MTP provider, phone sources are *absent with the
//! stated reason* — never a silent gap.

use crate::model::PhotoKind;

#[derive(Clone, Debug)]
pub enum ImportSource {
    /// Local directory (desktop USB/SD mass storage).
    LocalDir { path: String },
    /// MTP/PTP via a registered provider — USB "File transfer".
    Mtp { device: String, path: String },
    /// No provider registered: the honest degrade (§6.8 rule).
    MtpUnavailable { reason: String },
}

impl ImportSource {
    pub fn is_read_only(&self) -> bool {
        self.read_only()
    }
    pub fn is_removable(&self) -> bool {
        !matches!(self, ImportSource::LocalDir { .. })
    }
    pub fn read_only(&self) -> bool {
        matches!(self, ImportSource::Mtp { .. } | ImportSource::MtpUnavailable { .. })
    }
    /// Probe: what does this source offer right now?
    pub fn probe(&self) -> Result<(), String> {
        match self {
            ImportSource::LocalDir { .. } | ImportSource::Mtp { .. } => Ok(()),
            ImportSource::MtpUnavailable { reason } => Err(reason.clone()),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Stack {
    pub base: String,
    pub members: Vec<String>,
    pub kind: PhotoKind,
}

/// Group RAW+JPEG pairs (`IMG_0001.CR2` + `IMG_0001.JPG` = one tile).
pub fn group_stacks(names: &[String]) -> Vec<Stack> {
    let mut by_stem: std::collections::HashMap<String, Vec<String>> = std::collections::HashMap::new();
    for n in names {
        let stem = match n.rfind('.') {
            Some(i) => &n[..i],
            None => n,
        };
        by_stem.entry(stem.to_string()).or_default().push(n.clone());
    }
    let mut stacks = Vec::new();
    let mut stems: Vec<_> = by_stem.keys().cloned().collect();
    stems.sort();
    for stem in stems {
        let members = &by_stem[&stem];
        if members.len() > 1 {
            let has_raw = members.iter().any(|m| {
                m.rsplit('.').next().map(|e| crate::model::is_raw_ext(e)).unwrap_or(false)
            });
            stacks.push(Stack {
                base: stem.clone(),
                members: members.clone(),
                kind: if has_raw { PhotoKind::Raw } else { PhotoKind::Image },
            });
        }
    }
    stacks
}

#[derive(Clone, Debug)]
pub struct ImportReport {
    pub imported: usize,
    pub skipped_duplicates: usize,
    pub stacks: usize,
}

/// Import into the library by contentHash dedup. `existing_hashes` are the
/// hashes already indexed. Dropped images land here too (§9.2 drag-drop).
pub fn import_files(
    files: &[(String, String)],
    existing_hashes: &std::collections::HashSet<String>,
) -> ImportReport {
    let mut imported = 0;
    let mut skipped_duplicates = 0;
    let mut names = Vec::new();
    for (name, hash) in files {
        if existing_hashes.contains(hash) {
            skipped_duplicates += 1;
        } else {
            imported += 1;
            names.push(name.clone());
        }
    }
    let stacks = group_stacks(&names).len();
    ImportReport { imported, skipped_duplicates, stacks }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn mtp_unavailable_is_honest() {
        let s = ImportSource::MtpUnavailable { reason: "no MTP provider registered".into() };
        assert!(s.probe().is_err());
        assert!(s.read_only());
    }

    #[test]
    fn raw_jpeg_pairs_group_into_stacks() {
        let names = vec!["IMG_0001.CR2".to_string(), "IMG_0001.JPG".to_string(), "IMG_0002.JPG".to_string()];
        let stacks = group_stacks(&names);
        assert_eq!(stacks.len(), 1);
        assert_eq!(stacks[0].kind, PhotoKind::Raw);
    }

    #[test]
    fn import_dedups_by_content_hash() {
        let existing: HashSet<String> = HashSet::from(["h1".to_string()]);
        let rep = import_files(
            &[("a.jpg".into(), "h1".into()), ("b.jpg".into(), "h2".into())],
            &existing,
        );
        assert_eq!(rep.imported, 1);
        assert_eq!(rep.skipped_duplicates, 1);
    }
}

//! Picker — generic system picker with New Folder / search / multi-select
//! (PHOTOS-SPECS §9.3). Promotes the wallpaper picker to
//! `PickPurpose ∈ {Wallpaper, Open, Save, Import}` + optional format filter.

use std::collections::HashSet;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PickPurpose {
    Wallpaper,
    Open,
    Save,
    Import,
}

impl PickPurpose {
    /// Wallpaper stays single-select; everything else may multi-select.
    pub fn is_single(&self) -> bool {
        matches!(self, PickPurpose::Wallpaper)
    }
}

#[derive(Clone, Debug)]
pub struct PickerState {
    pub purpose: PickPurpose,
    pub dir: String,
    pub query: String,
    pub search_everywhere: bool,
    pub selected: HashSet<String>,
    pub show_hidden: bool,
    pub format: String,
    pub sort: String,
}

impl PickerState {
    pub fn new(purpose: PickPurpose, dir: String) -> Self {
        Self {
            purpose,
            dir,
            query: String::new(),
            search_everywhere: false,
            selected: HashSet::new(),
            show_hidden: false,
            format: "All".into(),
            sort: "name".into(),
        }
    }

    pub fn can_multi(&self) -> bool {
        !self.purpose.is_single()
    }

    pub fn toggle(&mut self, path: String) {
        if self.purpose.is_single() {
            self.selected.clear();
            self.selected.insert(path);
        } else if !self.selected.insert(path.clone()) {
            self.selected.remove(&path);
        }
    }

    /// Footer: "N selected · M MB".
    pub fn footer(&self, sizes: impl Fn(&str) -> u64) -> String {
        let total: u64 = self.selected.iter().map(|p| sizes(p)).sum();
        format!("{} selected · {} MB", self.selected.len(), total / (1024 * 1024))
    }

    pub fn choose_label(&self) -> String {
        match self.purpose {
            PickPurpose::Wallpaper => "Set as Wallpaper".into(),
            PickPurpose::Open => format!("Choose {}", self.selected.len().max(1)),
            PickPurpose::Save => "Save".into(),
            PickPurpose::Import => format!("Import {}", self.selected.len()),
        }
    }
}

/// Create a folder inline. Fails honestly on read-only sources ("A folder by
/// that name exists" / "This device is read-only").
pub fn new_folder(dir: &str, name: &str, writable: bool, exists: impl Fn(&str) -> bool) -> Result<String, String> {
    if name.trim().is_empty() {
        return Err("Enter a folder name.".into());
    }
    if !writable {
        return Err("This device is read-only — a folder cannot be created here.".into());
    }
    let path = format!("{}/{}", dir.trim_end_matches('/'), name.trim());
    if exists(&path) {
        return Err("A folder by that name exists.".into());
    }
    Ok(path)
}

/// Format filter row (All / JPEG / PNG / HEIC / RAW / Video) driven by §4.5
/// kinds; demoted kinds are listed with their reason, never hidden silently.
pub fn format_options() -> Vec<(&'static str, &'static str)> {
    vec![
        ("All", "every kind"),
        ("JPEG", "decodable"),
        ("PNG", "decodable"),
        ("HEIC", "indexed — preview via embedded thumbnail or declared-unavailable"),
        ("RAW", "indexed + embedded JPEG preview"),
        ("Video", "ffmpeg stills when present"),
    ]
}

