mod tests {
    use super::*;

    #[test]
    fn wallpaper_is_single_select() {
        let mut p = PickerState::new(PickPurpose::Wallpaper, "/pic".into());
        p.toggle("a.jpg".into());
        p.toggle("b.jpg".into());
        assert_eq!(p.selected.len(), 1);
    }

    #[test]
    fn new_folder_validates() {
        assert!(new_folder("/pic", "2024", true, |_| false).is_ok());
        assert_eq!(new_folder("/pic", "x", false, |_| false).unwrap_err(), "This device is read-only — a folder cannot be created here.");
        assert_eq!(new_folder("/pic", "x", true, |_| true).unwrap_err(), "A folder by that name exists.");
    }
