//! Trash integration (PHOTOS-SPECS §9.4–9.5).
//!
//! **Trash is never confirmed.** It is undoable. **Permanent delete is
//! typed**: the dialog asks the user to type `delete` (§9.5). Empty Trash
//! shows count + total size, typed-confirm when > 1 GiB. Missing records in
//! the library stay tombstoned (§8.6) — Trash and Missing are different
//! concepts and the UI never merges them.

/// The exact typed confirmation for permanent delete.
pub const TYPE_TO_CONFIRM: &str = "delete";
/// Typed-confirm threshold: Empty Trash > 1 GiB.
pub const LARGE_TRASH_BYTES: u64 = 1 << 30;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DeleteAction {
    /// Move to Trash — undoable, no confirmation, toast with Undo.
    Trash,
    /// Permanent delete — typed-confirmed, undoable.
    Permanent { confirmation: String },
}

impl DeleteAction {
    pub fn is_typed_ok(&self) -> bool {
        match self {
            DeleteAction::Trash => true,
            DeleteAction::Permanent { confirmation } => confirmation == TYPE_TO_CONFIRM,
        }
    }
    pub fn describe(&self, name: &str, size: u64, count: usize) -> String {
        match self {
            DeleteAction::Trash => format!("Move {count} item(s) to Trash — undoable."),
            DeleteAction::Permanent { .. } => format!(
                "Delete {} field(s) permanently. {} will not come back.",
                count, name
            ),
        }
    }
}

/// Empty Trash requires typed confirmation when > 1 GiB.
pub fn empty_needs_typed(total_bytes: u64, confirmation: &str) -> bool {
    total_bytes > LARGE_TRASH_BYTES && confirmation != TYPE_TO_CONFIRM
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn trash_never_needs_confirmation() {
        assert!(DeleteAction::Trash.is_typed_ok());
    }

    #[test]
    fn permanent_requires_exact_lowercase_delete() {
        assert!(DeleteAction::Permanent { confirmation: "delete".into() }.is_typed_ok());
        assert!(!DeleteAction::Permanent { confirmation: "Delete".into() }.is_typed_ok());
        assert!(!DeleteAction::Permanent { confirmation: "yes".into() }.is_typed_ok());
    }

    #[test]
    fn large_empty_needs_typed() {
        assert!(empty_needs_typed(2 << 30, "nope"));
        assert!(!empty_needs_typed(2 << 30, "delete"));
        assert!(!empty_needs_typed(100, "nope"));
    }
}

//! Capture (camera + screen, protocol-shaped) — PHOTOS-SPECS §6.10.
//!
//! Camera: `capturePhoto` with `PhotoOptions` (format, HDR, filter chain,
//! watermark), `setZoom`/`setFlash`/`setFocus`/`setExposureCompensation`,
//! `getRichMetadata` for the capture record. Screen: the working
//! screenshot path is kept; record uses a capability probe — a missing
//! backend is an honest "Recording isn't available here — <reason>",
//! never a fake success (LIE-5). Every capture lands in `Pictures` and is
//! `contentHash`-indexed like any other photo.

use crate::protocol::{CameraGateway, CaptureOptions};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CaptureMode {
    Camera,
    Screen,
    Video,
}

#[derive(Clone, Debug)]
pub struct Capture {
    pub mode: CaptureMode,
    pub dest: String,
    pub hash: String,
}

impl Capture {
    /// Every capture lands in Pictures and is contentHash-indexed.
    pub fn ingest(mut self, hash: String) -> Self {
        self.hash = hash;
        self
    }
}

/// Screen capture is always real (desktop). Camera/video depend on the
/// registered provider — honest when absent.
pub fn probe(mode: CaptureMode, camera: &dyn CameraGateway) -> Result<(), String> {
    match mode {
        CaptureMode::Screen => Ok(()),
        CaptureMode::Camera | CaptureMode::Video => camera.probe_available(),
    }
}

/// Capture via the protocol camera gateway.
pub fn capture_photo(mode: CaptureMode, camera: &dyn CameraGateway) -> Result<Capture, String> {
    match mode {
        CaptureMode::Screen => Ok(Capture {
            mode,
            dest: "Pictures".into(),
            hash: String::new(),
        }),
        CaptureMode::Camera | CaptureMode::Video => {
            let dest = camera.capture_photo(&CaptureOptions::default())?;
            Ok(Capture { mode, dest, hash: String::new() })
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::protocol::UnavailableCamera;

    #[test]
    fn screen_is_real_without_a_provider() {
        assert!(probe(CaptureMode::Screen, &UnavailableCamera).is_ok());
    }

    #[test]
    fn camera_without_provider_says_why() {
        let err = probe(CaptureMode::Camera, &UnavailableCamera).unwrap_err();
        assert!(err.contains("unavailable"));
    }
}

//! Accessibility (PHOTOS-SPECS §9.1).
//!
//! Keyboard completeness, focus visibility, screen-reader labels, motion,
//! contrast & type, targets, colour independence. State is never colour-only:
//! selection = 2 px border, favourite = filled heart, missing = hatch +
//! label, loading = skeleton + shimmer.

/// Focus ring: 2 px; 3 px in high contrast. Inset 2 px out of the gutter.
pub const FOCUS_RING_PX: f32 = 2.0;
pub const FOCUS_RING_HC_PX: f32 = 3.0;
pub const FOCUS_INSET_PX: f32 = 2.0;
/// Targets: ≥ 44 px desktop / 40 px phone per control.
pub const TARGET_DESKTOP_PX: f32 = 44.0;
pub const TARGET_PHONE_PX: f32 = 40.0;
/// Nothing under 12 px; chrome ≤ 18 px.
pub const MIN_TEXT_PX: f32 = 12.0;
pub const MAX_CHROME_PX: f32 = 18.0;
/// Type-ahead 800 ms.
pub const TYPEAHEAD_MS: u64 = 800;

pub fn ring_px(high_contrast: bool) -> f32 {
    if high_contrast {
        FOCUS_RING_HC_PX
    } else {
        FOCUS_RING_PX
    }
}

pub fn target_px(phone: bool) -> f32 {
    if phone {
        TARGET_PHONE_PX
    } else {
        TARGET_DESKTOP_PX
    }
}

/// `reduced_motion` disables springs, crossfade and Ken Burns.
pub fn motion_factor(reduced_motion: bool) -> f32 {
    if reduced_motion {
        0.0
    } else {
        1.0
    }
}

/// Selection = 2 px border; favourite = filled heart; missing = hatch + label.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CellState {
    Selected,
    Favourite,
    Missing,
    Loading,
    Broken,
    Unpreviewable,
    Normal,
}

/// Every cell renders a shape + label, never colour only.
pub fn cell_annotation(state: CellState) -> &'static str {
    match state {
        CellState::Selected => " selected — 2 px border",
        CellState::Favourite => " favourite — filled heart",
        CellState::Missing => " missing — hatch + label",
        CellState::Loading => " loading — skeleton + shimmer",
        CellState::Broken => " could not open — Retry",
        CellState::Unpreviewable => " no preview — <reason>",
        CellState::Normal => "",
    }
}

