//! Viewer, filmstrip, slideshow, compare (PHOTOS-SPECS §7.1).
//!
//! Zoom 1%–6400% with **zoom-to-cursor**: `pan_new = c − (c−pan)·(new/old)`,
//! presets Fit/Fill/100/200/300/Free. `Actual size` means 100% of original
//! pixels (LIE-1 fix — no 1600 px cap). The viewer never releases the
//! previous texture before the next upload completes (no flicker, A6).

/// Zoom bounds 1%–6400%, presets 100/200/300.
pub const ZOOM_MIN: f32 = 0.01;
pub const ZOOM_MAX: f32 = 64.0;
/// Zoom step: 140 ms `ease_out_cubic`.
pub const ZOOM_STEP_MS: u64 = 140;
/// Preload: ±2 display, ±1 zoom.
pub const PRELOAD_DISPLAY: usize = 2;
/// Uploads/frame ≤ 8, skipped above 2 px scroll.
pub const MAX_UPLOADS_PER_FRAME: usize = 8;
pub const SCROLL_SKIP_PX: f32 = 2.0;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Zoom {
    Fit,
    Fill,
    P100,
    P200,
    P300,
    Free(f32),
}

impl Zoom {
    pub fn factor(&self, canvas: f32, img: f32) -> f32 {
        match self {
            Zoom::Fit => if img > 0.0 { (canvas / img).min(1.6) * 0.96 } else { 1.0 },
            Zoom::Fill => if img > 0.0 { (canvas / img).max(1.0) } else { 1.0 },
            Zoom::P100 => 1.0,
            Zoom::P200 => 2.0,
            Zoom::P300 => 3.0,
            Zoom::Free(f) => *f,
        }
    }
    pub fn step(cur: f32, dir: f32) -> f32 {
        // §7.1 ease-out step toward the target zoom.
        let target = zoom_presets().iter().copied().find(|z| (z - 1.0).abs() < 0.001)
            .unwrap_or(1.0);
        let _ = target;
        (cur * dir).clamp(ZOOM_MIN, ZOOM_MAX)
    }
}

pub fn zoom_presets() -> Vec<f32> {
    vec![1.0, 2.0, 3.0]
}

/// Zoom-to-cursor — the exact F9 formula:
/// `pan_new = c − (c−pan)·(new/old)`.
pub fn zoom_to_cursor(pan: f32, cursor: f32, old_zoom: f32, new_zoom: f32) -> f32 {
    if old_zoom <= 0.0 {
        return pan;
    }
    cursor - (cursor - pan) * (new_zoom / old_zoom)
}

#[derive(Clone, Debug)]
pub struct Viewer {
    pub zoom: Zoom,
    pub zoom_f: f32,
    pub pan: f32,
    pub compare_hold: bool,
    pub slideshow: bool,
    pub slideshow_secs: f32,
    pub slide_t: f64,
    pub filmstrip_visible: bool,
    pub index: usize,
    pub count: usize,
}

impl Default for Viewer {
    fn default() -> Self {
        Self {
            zoom: Zoom::Fit,
            zoom_f: 1.0,
            pan: 0.0,
            compare_hold: false,
            slideshow: false,
            slideshow_secs: 5.0,
            slide_t: 0.0,
            filmstrip_visible: true,
            index: 0,
            count: 0,
        }
    }
}

impl Viewer {
    /// Wrap-around navigation (rem_euclid).
    pub fn nav(&mut self, delta: isize) {
        if self.count == 0 {
            return;
        }
        self.index = (self.index as isize + delta).rem_euclid(self.count as isize) as usize;
        self.slide_t = 0.0;
    }
    /// Hold-compare: shows the original alongside the edited render.
    pub fn held_image(&self) -> &'static str {
        if self.compare_hold { "ORIGINAL" } else { "EDITED" }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn zoom_to_cursor_keeps_point_stable() {
        // The point under the cursor stays under the cursor.
        let pan = zoom_to_cursor(10.0, 100.0, 1.0, 2.0);
        assert!((pan - (100.0 - (100.0 - 10.0) * 2.0)).abs() < 1e-6);
    }

    #[test]
    fn nav_wraps() {
        let mut v = Viewer { index: 0, count: 3, ..Viewer::default() };
        v.nav(-1);
        assert_eq!(v.index, 2);
    }

    #[test]
    fn actual_size_is_real_pixels() {
        // 100% of original pixels — the LIE-1 fix.
        assert_eq!(Zoom::P100.factor(800.0, 6000.0), 1.0);
    }
}

