//! EXIF + orientation (PHOTOS-SPECS §8.3–8.4).
//!
//! Reads at most the first 128 KiB (EXIF bound). `taken_at` resolution order:
//! **DateTimeOriginal → DateTimeDigitized → DateTime → filename (4 shapes
//! only) → container → mtime → Unknown** (badged, never guessed). A general
//! date-from-string is forbidden — that is how a library fills up with
//! photographs from 2001.

use crate::model::TakenSource;

/// EXIF bound: first 128 KiB.
pub const EXIF_BOUND: usize = 128 << 10;
/// Header bound: 64 KiB for probe.
pub const HEADER_BOUND: usize = 64 << 10;

#[derive(Clone, Debug, Default)]
pub struct ExifInfo {
    pub camera: String,
    pub lens: String,
    pub orientation: u8,
    pub gps: Option<(f64, f64, Option<f64>)>,
    pub taken_at: Option<i64>,
    pub taken_source: TakenSource,
}

/// Oriented dimensions: EXIF orientations 5–8 swap width/height.
pub fn oriented(w: u32, h: u32, orientation: u8) -> (u32, u32) {
    if (5..=8).contains(&orientation) {
        (h, w)
    } else {
        (w, h)
    }
}

/// Parse EXIF from the first `EXIF_BOUND` bytes. Returns defaults on failure
/// (a missing EXIF is a state, never an error).
pub fn parse_exif(bytes: &[u8]) -> ExifInfo {
    let head = &bytes[..bytes.len().min(EXIF_BOUND)];
    let reader = exif::Reader::new();
    match reader.read_from_container(&mut std::io::Cursor::new(head)) {
        Ok(exif) => exif_to_info(&exif),
        Err(_) => ExifInfo::default(),
    }
}

fn exif_to_info(exif: &exif::Exif) -> ExifInfo {
    let mut info = ExifInfo::default();
    // Camera make + model (honest: either read from the file or empty).
    let make = get_str(exif, exif::Tag::Make);
    let model = get_str(exif, exif::Tag::Model);
    info.camera = match (make.is_empty(), model.is_empty()) {
        (true, true) => String::new(),
        (false, true) => make,
        (true, false) => model,
        (false, false) => format!("{make} {model}"),
    };
    info.lens = get_str(exif, exif::Tag::LensModel);
    // Orientation tag.
    for tag in [exif::Tag::Orientation] {
        if let Some(f) = exif.get_tag(tag) {
            if let exif::Value::Short(v) = &f.value {
                info.orientation = v.first().copied().unwrap_or(1);
                break;
            }
        }
    }
    // GPS latitude/longitude.
    let lat = get_gps(exif, true);
    let lon = get_gps(exif, false);
    if let (Some(la), Some(lo)) = (lat, lon) {
        info.gps = Some((la, lo, None));
    }
    // taken_at order (§8.3).
    if let Some(t) = datetime_of(exif, exif::Tag::DateTimeOriginal) {
        info.taken_at = Some(t);
        info.taken_source = TakenSource::ExifOriginal;
    } else if let Some(t) = datetime_of(exif, exif::Tag::DateTimeDigitized) {
        info.taken_at = Some(t);
        info.taken_source = TakenSource::ExifDigitized;
    } else if let Some(t) = datetime_of(exif, exif::Tag::DateTime) {
        info.taken_at = Some(t);
        info.taken_source = TakenSource::Exif;
    }
    info
}

fn get_str(exif: &exif::Exif, tag: exif::Tag) -> String {
    if let Some(f) = exif.get_tag(tag) {
        let s = f.display().trim().trim_matches('"').trim_end_matches('\0').to_string();
        if !s.is_empty() && s != "None" {
            return s;
        }
    }
    String::new()
}

fn get_gps(exif: &exif::Exif, lat: bool) -> Option<f64> {
    let tag = if lat { exif::Tag::GPSLatitude } else { exif::Tag::GPSLongitude };
    let rtag = if lat { exif::Tag::GPSLatitudeRef } else { exif::Tag::GPSLongitudeRef };
    let f = exif.get_tag(tag)?;
    let g = exif.get_tag(rtag)?;
    let nums: Vec<f64> = match &f.value {
        exif::Value::Rational(v) => v.iter().map(|r| r.num as f64 / r.denom.max(1) as f64).collect(),
        _ => return None,
    };
    if nums.len() < 3 {
        return None;
    }
    let mut deg = nums[0] + nums[1] / 60.0 + nums[2] / 3600.0;
    let r = g.display();
    if r.contains('S') || r.contains('W') {
        deg = -deg;
    }
    Some(deg)
}

fn datetime_of(exif: &exif::Exif, tag: exif::Tag) -> Option<i64> {
    let f = exif.get_tag(tag)?;
    parse_exif_datetime(&f.display())
}

pub fn parse_exif_datetime(s: &str) -> Option<i64> {
    // Cheap parser for the four EXIF shapes; uses chrono for the rest.
    let s = s.trim().trim_matches('"').trim_end_matches('\0');
    let naive = chrono::NaiveDateTime::parse_from_str(s, "%Y:%m:%d %H:%M:%S").ok()
        .or_else(|| chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S").ok())?;
    Some(naive.and_utc().timestamp())
}

/// The four filename shapes only (§8.3 / §11.4). Any other shape → `None`,
/// which falls through to container → mtime → Unknown (never guessed).
/// * `YYYYMMDD_HHMMSS` · `YYYYMMDD-HHMMSS` · `YYYY-MM-DD HH.MM.SS` · `YYYY-MM-DD`
pub fn taken_from_filename(name: &str) -> Option<i64> {
    let base = name.rsplit('/').next().unwrap_or(name);
    // YYYYMMDD_HHMMSS or YYYYMMDD-HHMMSS
    if let Some(v) = parse_compact(base, b'_') {
        return Some(v);
    }
    if let Some(v) = parse_compact(base, b'-') {
        return Some(v);
    }
    // YYYY-MM-DD HH.MM.SS (or with T)
    let with_space: String = base.replace(['T', '.'], " ");
    if let Some(v) = parse_exif_datetime(&with_space) {
        return Some(v);
    }
    // Plain YYYY-MM-DD
    if let Some(v) = parse_date_only(base) {
        return Some(v);
    }
    None
}

fn parse_compact(base: &str, sep: u8) -> Option<i64> {
    let stem = match base.rfind('.') {
        Some(i) if i > 6 => &base[..i],
        _ => base,
    };
    let pos = stem.bytes().position(|c| c == sep)?;
    let (d, t) = stem.split_at(pos);
    let t = &t[1..];
    if d.len() != 8 || t.len() != 6 || !d.bytes().all(|c| c.is_ascii_digit()) || !t.bytes().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let s = format!("{}:{}:{} {}:{}:{}", &d[0..4], &d[4..6], &d[6..8], &t[0..2], &t[2..4], &t[4..6]);
    parse_exif_datetime(&s)
}

fn parse_date_only(base: &str) -> Option<i64> {
    let stem = match base.rfind('.') {
        Some(i) => &base[..i],
        None => base,
    };
    let d = chrono::NaiveDate::parse_from_str(stem, "%Y-%m-%d").ok()?;
    Some(d.and_hms_opt(0, 0, 0)?.and_utc().timestamp())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn orientation_swaps_for_5_to_8() {
        assert_eq!(oriented(100, 50, 1), (100, 50));
        assert_eq!(oriented(100, 50, 6), (50, 100));
        assert_eq!(oriented(100, 50, 8), (50, 100));
        assert_eq!(oriented(100, 50, 0), (100, 50));
    }

    #[test]
    fn taken_shapes_are_strict() {
        assert!(taken_from_filename("20231109_143052.jpg").is_some());
        assert!(taken_from_filename("2023-11-09 14.30.52.jpg").is_some());
        assert!(taken_from_filename("IMG_0001.jpg").is_none(), "never guess a general date");
        assert!(taken_from_filename("2001-union.jpg").is_none(), "the 2001 trap");
    }

    #[test]
    fn exif_datetime_parses_or_fails_honestly() {
        assert!(parse_exif_datetime("2023:11:09 14:30:52").is_some());
        assert!(parse_exif_datetime("not-a-date").is_none());
    }
}

