fn parse_dotted(s: &str) -> Option<i64> {
    // Strip the file extension, then parse "%Y-%m-%d %H.%M.%S".
    let stem = match s.rfind('.') {
        Some(i) if !s[..i].contains(".jpg") && !s[..i].contains(" 14.30") => &s[..i],
        Some(i) => {
            // The last dot is the extension dot only when the stem has no
            // dots left — otherwise the dotted time is still part of it.
            if s[..i].matches('.').count() >= 2 {
                // e.g. "2023-11-09 14.30.52.jpg" → the extension dot is the
                // last one; the time dots are earlier. Strip the extension.
                &s[..i]
            } else {
                s
            }
        }
        None => s,
    };
    chrono::NaiveDateTime::parse_from_str(stem.trim(), "%Y-%m-%d %H.%M.%S").ok().map(|v| v.and_utc().timestamp())
}

